<?php declare(strict_types=1); require_once __DIR__.'/../includes/auth.php'; require_auth(); if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: ?page=cabinet');exit;} verify_csrf(); $plan=$_POST['plan']??'free'; if(!in_array($plan,['free','standard','pro'],true))$plan='free'; $pdo=db(); $pdo->beginTransaction(); $pdo->prepare('UPDATE subscriptions SET status="cancelled" WHERE user_id=? AND status="active"')->execute([$_SESSION['user_id']]); $pdo->prepare('INSERT INTO subscriptions(user_id,plan,status) VALUES(?,?,"active")')->execute([$_SESSION['user_id'],$plan]); $pdo->commit(); header('Location: ?page=cabinet');
